#!/usr/bin/env bash
#
# Reproduce the Navigation API cross-engine observation probe.
# Third-party runnable:
#
#     git clone https://github.com/var-gg/benchmarks
#     cd benchmarks/runs/2026-07-24-navigation-api-spa-routing
#     ./run.sh
#
# Produces: probe-result.json (per-engine surface + 11-trigger observation matrix +
# history stack readout + spa intercept result). Compare it against results.json.
#
# NOTE: router-check.json (whether shipped React routers reference the Navigation API)
# is NOT regenerated by this script — it was produced by `npm pack`-ing react-router and
# @tanstack/history and grepping their dist. See router-check.json for the method; the
# versions there pin what was checked on 2026-07-24.
#
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
cd "$HERE"

EXPECTED="chromium 147.0.7727.15 / firefox 148.0.2 / webkit 26.4"

echo "==> Creating isolated Python environment"
python -m venv .venv
# Windows Git Bash uses Scripts/; POSIX uses bin/.
if [ -f .venv/Scripts/activate ]; then source .venv/Scripts/activate; else source .venv/bin/activate; fi

echo "==> Installing pinned Playwright (ships ${EXPECTED})"
pip install -q -r requirements.txt

echo "==> Installing the three engine builds under test"
python -m playwright install chromium firefox webkit

echo "==> Running the probe across all three engines"
python probe.py --engines chromium,firefox,webkit --out probe-result.json

echo
echo "==> Done. Wrote probe-result.json"
echo "    Confirm each engine version matches manifest.json.subject.engines."
echo "    Reminder: Playwright's WebKit is NOT Safari. window.navigation is absent in the"
echo "    WebKit build; that is an observation about the Playwright E2E environment, not Safari."
